! ============================================================
! VML 调试扩展库 — Fortran
!
! 使用示例:
!   call asm("SYSCALL 70")     ! 输出调试字符串
!   call asm("SYSCALL 71")     ! 输出调试整数
!   call asm("SYSCALL 72")     ! 断言检查
!
! 注意: 输出到 stderr 而非 stdout
! ============================================================

! ============================================================
! SYSCALL 70 — DebugPrint
! 输出调试字符串到 stderr
! 参数: R0 = 字符串地址 (以 \0 结尾)
! 返回值: 无
!
! Fortran 使用示例:
!   ! 假设字符串 "Hello Debug\n" 已写入内存地址 addr
!   call asm("STORE addr, R0")
!   call asm("SYSCALL 70")
! ============================================================

! ============================================================
! SYSCALL 71 — DebugPrintInt
! 输出整数到 stderr
! 参数: R0 = 整数值
! 返回值: 无
!
! Fortran 使用示例:
!   ! 输出值 42
!   call asm("STORE 42, R0")
!   call asm("SYSCALL 71")
! ============================================================

! ============================================================
! SYSCALL 72 — Assert
! 断言检查。条件为假时输出错误信息并终止程序
! 参数:
!   R0 = 条件值 (0=假, 非0=真)
!   R1 = 失败消息字符串地址
! 返回值: 无 (条件为假时终止程序)
!
! Fortran 使用示例:
!   ! 检查指针是否非空
!   ! R0 = 指针值, R1 = 错误消息地址
!   call asm("SYSCALL 72")
! ============================================================

! ============================================================
! 通用调试模式:
!   ! 打印变量值用于调试
!   call asm("SYSCALL 6")      ! 先用 SYSCALL 6 打印整数
!
!   ! 或通过 DebugPrintInt 输出到 stderr
!   call asm("SYSCALL 71")
! ============================================================
